import sys
import os
import json

def parse_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val or val.lower() in ("n/a", "none", "null"):
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    parts = val.split('-')
    if len(parts) == 3 and len(parts[0]) == 4 and len(parts[1]) == 2 and len(parts[2]) == 2:
        return val
    return val

FACT_FIELD_MAP = {
    "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
    "classification date": ("fda_enforcement_reports", "center_classification_date"),
    "termination date": ("fda_enforcement_reports", "termination_date")
}

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    fda_file_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    enforcement_reports = []
    if os.path.exists(fda_file_path):
        with open(fda_file_path, "r", encoding="utf-8") as f:
            data = json.load(f)
            enforcement_reports = data.get("results", [])

    reports_by_recall = {}
    for item in enforcement_reports:
        rec_num = item.get("recall_number")
        if rec_num:
            rec_num_clean = str(rec_num).strip()
            reports_by_recall.setdefault(rec_num_clean, []).append(item)

    pairs = manifest.get("pairs", [])
    facts_config = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        entity_clean = entity.strip()

        rule_facts = facts_config.get(rule_id, [])
        matching_reports = reports_by_recall.get(entity_clean, [])

        pair_result = {}
        for fact_name in rule_facts:
            mapping = FACT_FIELD_MAP.get(fact_name)
            if not mapping:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, field_name = mapping
            values = set()
            for report in matching_reports:
                raw_val = report.get(field_name)
                parsed = parse_date(raw_val)
                if parsed is not None:
                    values.add(parsed)

            if len(values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact_name] = [next(iter(values)), doc_name]
            else:
                pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
