import sys
import json
import os
import re

FACT_MAP = {
    "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
    "classification date": ("fda_enforcement_reports", "center_classification_date"),
    "termination date": ("fda_enforcement_reports", "termination_date"),
}

def format_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val or val.upper() == "N/A":
        return None
    m = re.match(r"^(\d{4})(\d{2})(\d{2})$", val)
    if m:
        return f"{m.group(1)}-{m.group(2)}-{m.group(3)}"
    if re.match(r"^\d{4}-\d{2}-\d{2}$", val):
        return val
    return val

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    fda_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    records_by_recall = {}
    if os.path.exists(fda_file):
        with open(fda_file, "r", encoding="utf-8") as f:
            data = json.load(f)
            for row in data.get("results", []):
                rn = row.get("recall_number")
                if rn:
                    records_by_recall.setdefault(rn, []).append(row)

    output = {}
    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        facts = facts_spec.get(rule_id, [])
        pair_result = {}

        for fact in facts:
            if fact not in FACT_MAP:
                pair_result[fact] = "ABSENT"
                continue

            doc_name, field_name = FACT_MAP[fact]
            records = records_by_recall.get(entity, [])
            vals = set()

            for r in records:
                formatted = format_date(r.get(field_name))
                if formatted:
                    vals.add(formatted)

            if len(vals) == 0:
                pair_result[fact] = "ABSENT"
            elif len(vals) == 1:
                pair_result[fact] = [list(vals)[0], doc_name]
            else:
                pair_result[fact] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
