```python
import sys
import os
import json
import re
from pathlib import Path

FACT_MAPPING = {
    "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
    "classification date": ("fda_enforcement_reports", "center_classification_date"),
    "termination date": ("fda_enforcement_reports", "termination_date"),
}

def format_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val or val.upper() == "N/A":
        return None
    m = re.match(r"^(\d{4})(\d{2})(\d{2})$", val)
    if m:
        return f"{m.group(1)}-{m.group(2)}-{m.group(3)}"
    m = re.match(r"^\d{4}-\d{2}-\d{2}$", val)
    if m:
        return val
    return val

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = Path(sys.argv[1])
    manifest_path = Path(sys.argv[2])

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load fda_enforcement_reports
    fda_data = {}
    fda_file = packet_dir / "fda_enforcement_reports.json"
    if fda_file.exists():
        with open(fda_file, "r", encoding="utf-8") as f:
            content = json.load(f)
            results = content.get("results", [])
            for item in results:
                recall_num = item.get("recall_number")
                if recall_num:
                    fda_data.setdefault(recall_num, []).append(item)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        rule_id, entity_id = pair.split("::", 1)
        facts = facts_spec.get(rule_id, [])
        pair_result = {}

        records = fda_data.get(entity_id, [])

        for fact_name in facts:
            doc_name, field_name = FACT_MAPPING.get(
                fact_name,
                ("fda_enforcement_reports", fact_name.replace(" ", "_"))
            )

            is_date = "date" in fact_name or "date" in field_name

            values = set()
            for record in records:
                raw_val = record.get(field_name)
                if is_date:
                    formatted = format_date(raw_val)
                    if formatted is not None:
                        values.add(formatted)
                else:
                    if raw_val is not None:
                        val_str = str(raw_val).strip()
                        if val_str and val_str.upper() != "N/A":
                            values.add(val_str)

            if len(values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(values) > 1:
                pair_result[fact_name] = "CONFLICT"
            else:
                pair_result[fact_name] = [list(values)[0], doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
```

